"""Measured v36b population delivery with all receipts and scope limits."""
import sys,json,hashlib,collections
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent));import pop36_support as v
scores=[json.loads(p.read_text())for p in v.OUT.glob('*/*.score.json')];gates=[]
for p in v.OUT.glob('*/*.gate.json'):
 g=json.loads(p.read_text())
 if not g.get('gated'):continue
 assert set(g['MC3'])=={'0','1000','2000'},('incomplete MC3',p)
 st=Path(g['stem']);assert hashlib.sha256(st.with_suffix('.qasm').read_bytes()).hexdigest()==g['qasm_sha256'];gates.append(g)
gates.sort(key=lambda r:r['loss']);best=gates[0];st=Path(best['stem']);md=json.loads(st.with_suffix('.json').read_text())
lines=[f"**Best verified: `{st.relative_to(v.H)}` — all-orders {best['loss']:.12e}, acceptance {best['allorders_acceptance']:.9f}; judge PASS, XTIM FAST; MC3 mean {best['MC3_mean']:.9e}.**",'', '# ST2 — v36b population', '',f"Complete. Base MAIN/v36b: {v.a.BASE_LOSS:.12e}, acceptance {v.a.BASE_ACC:.12f}. Verification floor: 0.5002. Best expected gain: {v.a.BASE_LOSS-best['loss']:.9e} ({100*(v.a.BASE_LOSS-best['loss'])/v.a.BASE_LOSS:.5f}%). Winner: {md['cx']} CX, R{md['R']}, {md['native_depth']} native ticks.", '', 'Delivery: [best.qasm](best.qasm), [best.json](best.json), [best.verify.json](best.verify.json). QASM is byte-identical to the source finalist above. Exact native edits relative to v36b: [best_changes.json](pop36b/best_changes.json).', '', '| Finalist under ST2 | All-orders loss | Acceptance | Judge acceptance / s per million | XTIM s per million | MC3 mean |','|---|---:|---:|---:|---:|---:|']
for g in gates:lines.append(f"| `{Path(g['stem']).relative_to(v.H)}` | {g['loss']:.12e} | {g['allorders_acceptance']:.9f} | {g['judge_acceptance']:.6f} / {g['judge_seconds']:.3f} | {g['speed']['median_seconds_per_1e6']:.3f} | {g['MC3_mean']:.9e} |")
lines+=['','All listed finalists passed unchanged judge1e6, measured XTIM FAST, and official MC at 100M shots each for seeds0/1000/2000. Rank uses the full 72-observable canonical all-orders expectation, not one noisy seed or truncated fault order. The cutoff omission bound is stored per `.score.json` and excludes floating roundoff. No global optimum or server runtime guarantee is claimed.','','Re-derived generation-0 mechanisms:','', '- v36b already has q15/q21 and q20/q26 echoes. Folded q15 readout is retimed to a compatible q21 measurement; the short q20/q21 replacement uses CX33/34 because q20 has a data gate at35.', '- The old long q7 Z echo no longer directly fits: the new q7 window crosses Tdag29 and blue CX30. Its tested retimed version fails ideal detectors. Both a short Z window (CX27/28) and a long X window (CX27/31) were priced on v36b.', '- Guard274/275 measured-init parities, restored early known-zero measurements, checked q1 MX at7, q16@34 to q22@37 Tdag relocation, and acceptance-rich measurement removals were re-derived on native qubit lifetimes. The q14 initial reset is at0 on this base, so restoration locates the first operation rather than trusting old ticks.', '', 'Search and duplicate avoidance:', '', '- Every proposal first uses a lane-local copy of FRESH general_atoms.py/.cpp. This dispatch screen is diagnostic and does not modify xtim or the judge. Static FAST candidates are ranked by exact acceptance/loss; finalists still receive measured XTIM timing. Rejected and SLOW artifacts retain their cause.', '- Populations retain low-loss elites and candidates at measured loss/acceptance tradeoffs. Mutation families include timing slack, commuting gate order, measured versus reset init, MX/MZ helper bases, guard/echo endpoints and helper substitutions, guard274 exchanges, detector rows, new idle checks, whole-window timing, terminal-edge changes, phase transfers, and measured crossover patches.', '- Native fingerprints identify equivalent parallel-order and classical-record-label variants before repricing. FRESH owns general reuse/SX work; SEPBC owns incumbent integration. Their reports were read before work, and their standalone campaigns were not repeated.', '- The pre-cleanup TREP2/SCHED import paths were removed from core.py because ST2 already contains the required local schedule/util modules. No deleted dependency was needed or silently bypassed.', '',f"Scored alternatives: {len(scores)}. Feasible numerical results: {sum(r.get('eligible',False)and'loss'in r for r in scores)}. Finalist artifacts: {len(gates)}. Full index: [all_results.json](pop36b/all_results.json).",'']
for p in sorted(v.OUT.glob('*/generation_*.json')):
 r=json.loads(p.read_text());lines.append(f"- `{p.relative_to(v.OUT)}`: best {r['best']['loss']:.12e}, improvement {r['improvement']:.6e}, consecutive nonimproving generations {r['stagnant']}.")
lines+=['', 'Both islands continued while improving and stopped after two consecutive generations without improvement above1e-12. All controller/worker processes exited; no output file was used as a completion signal. The final report and stable delivery were checked against receipt hashes. All writes remained inside ST2; no credentials, submissions, commits, pushes or collaboration tools.', '', 'Prior work: [v35b report](pop36b/REPORT_before_v36.md).']
(v.H/'REPORT.md').write_text('\n'.join(lines)+'\n');(v.OUT/'all_results.json').write_text(json.dumps(dict(base_loss=v.a.BASE_LOSS,base_acceptance=v.a.BASE_ACC,acceptance_floor=v.a.FLOOR,scores=scores,gates=gates),indent=2))
p=v.k.patches(v.C.read(v.OUT/'base'),v.C.read(st));(v.OUT/'best_changes.json').write_text(json.dumps({key:sorted([list(x)if isinstance(x,tuple)else x for x in val],key=str)for key,val in p.items()},indent=2));print('BEST',str(st),best['loss'],best['allorders_acceptance'],best['MC3_mean'])
